5047: # (item 4, D1 / F09-3) What the init events of a turn prove - evidence first: every init must list
5048: # no tool outside Read, Grep, Glob, StructuredOutput, no MCP server and the permission mode dontAsk
5049: # (else class permission); and (item 6, F09-1) the credential the CLI took must be the roster's:
5050: # subscription - apiKeySource none; api-key - ANTHROPIC_API_KEY (else class auth: the turn billed
5051: # another way); (wave 29b, E3) endpoint - apiKeySource is none on this route too (P8, P10), so it
5052: # proves nothing: it is recorded raw, and only ANTHROPIC_API_KEY fails the turn (class auth: a
5053: # competing credential reached the child) - the proof of the route is the init model (D4, -Exact)
5054: # and child_env_allowed. { Problem ('' when proven or when there is no init - the caller decides);
5055: # Class }.
5056: function Get-ClaudeInitProblem {
5057:     param($Events, [string]$Auth = 'subscription')
5058:     $r = [pscustomobject]@{ Problem = ''; Class = '' }
5059:     if ([int]$Events.InitCount -le 0) { return $r }
5060:     $extra = @(@($Events.InitTools) | Where-Object { $script:ClaudeTools -cnotcontains [string]$_ })
5061:     if ($extra.Count -gt 0) { $r.Problem = "the init event lists tools outside $($script:ClaudeTools -join ', '): $($extra -join ', ') - the turn's read-only capability is not proven"; $r.Class = 'permission'; return $r }
5062:     if (@($Events.InitMcp).Count -gt 0) { $r.Problem = "the init event lists MCP server(s) ($(@($Events.InitMcp) -join ', ')) - a reviewer runs without any"; $r.Class = 'permission'; return $r }
5063:     $badMode = @(@($Events.InitModes) | Where-Object { [string]$_ -cne $script:ClaudePermissionMode }) | Select-Object -First 1
5064:     if ($null -ne $badMode) { $r.Problem = "the init event names the permission mode '$(ConvertTo-ClaudeToken ([string]$badMode))', not $($script:ClaudePermissionMode)"; $r.Class = 'permission'; return $r }
5065:     if ($Auth -eq 'endpoint') {
5066:         if (@(@($Events.InitKeySources) | Where-Object { [string]$_ -ceq 'ANTHROPIC_API_KEY' }).Count -gt 0) {
5067:             $r.Problem = 'the init event names apiKeySource ANTHROPIC_API_KEY on an endpoint route - a competing credential reached the child (auth endpoint sends ANTHROPIC_AUTH_TOKEN only)'
5068:             $r.Class = 'auth'
5069:         }
5070:         return $r
5071:     }
5072:     $want = $(if ($Auth -eq 'api-key') { 'ANTHROPIC_API_KEY' } else { 'none' })
5073:     $badKey = @(@($Events.InitKeySources) | Where-Object { [string]$_ -cne $want }) | Select-Object -First 1
5074:     if ($null -ne $badKey) {
5075:         $shown = $(if ([string]$badKey) { ConvertTo-ClaudeToken ([string]$badKey) } else { '(none named)' })
5076:         $r.Problem = "the init event names apiKeySource $shown, not $want - the turn did not bill $(if ($Auth -eq 'api-key') { 'the API key' } else { 'the claude.ai subscription' }) the roster names (auth $Auth)"
5077:         $r.Class = 'auth'
5078:         return $r
5079:     }
5080:     return $r
5081: }
