5083: # (item 3, D6) The wording of a usage limit and of a missing sign-in in claude's result text or
5084: # stderr ("Not logged in <middle dot> Please run /login" - obs; "... usage limit reached|<unix time>", "You've
5085: # hit your limit <middle dot> resets ...") - field names and wordings beyond the observed ones are assumed.
5086: # (wave 29b, E4) an endpoint route's 401/403 (P11: "Failed to authenticate. API Error: 401 ...") is
5087: # class auth; a 429 is class quota by its status (\b429\b) whatever its wording - extend the lists
5088: # after the first sightings of each provider's texts.
5089: $script:ClaudeQuotaRe = '(?i)usage limit|limit reached|hit your (?:usage |session |weekly )?limit|rate[ _]limit|weekly limit|session limit|quota|too many requests|\b429\b|credit balance is too low|overage'
5090: $script:ClaudeAuthRe = '(?i)not logged in|please run /login|invalid api key|oauth token (?:has )?(?:expired|revoked)|authentication[ _]error|failed to authenticate|api error: 40[13]\b|\b401\b|unauthori[sz]ed'
5091: 
5092: # The failure rules of one claude turn (the main turn, a denial retry, a format repair, a timeout
5093: # continuation) - the adapter contract of agy and muse plus -Turn (the turn's options: Mode, Thread,
5094: # NewThread, Model, Auth) and the fields ModelResolved and OtherModels:
5095: #   $Pre             a failure the bridge already knows (timeout, could not start) - it wins; a
5096: #                    rejecting rate_limit_event before it makes the class quota (no continuation)
5097: #   init proof       (item 4, item 6; evidence first, whatever the exit code) tools, MCP servers,
5098: #                    permission mode -> class permission; apiKeySource -> class auth
5099: #   exit != 0        failed: claude exit <n> - <result text | stderr>; quota or auth wording -> that
5100: #                    class
5101: #   malformed        class transport; no init event (exit 0) -> class permission (not proven); no
5102: #                    result -> failed (the init's session id is a candidate)
5103: #   the session      init and result must agree; a new thread must come back on the minted id, a
5104: #                    resume (every secondary turn) on its thread, a fork on a NEW uuid (not its
5105: #                    parent) - else class unknown, the id a candidate only
5106: #   is_error / subtype other than success -> failed: claude <subtype> - <text>; class quota (a
5107: #                    rejecting rate_limit_event or the limit wording - D6), auth (its wording),
5108: #                    capability (error_max_turns - D8 -, error_max_structured_output_retries)
5109: #   the model        (D4) the init model must be the pinned one (an alias: an id of its family);
5110: #                    modelUsage's main model must be it too - else class capability; a second key
5111: #                    is recorded (OtherModels) and warned about
5112: #   empty reply      with permission denials: failed, class permission, DeniedEmpty (the denial
5113: #                    retry); otherwise failed: empty reply
5114: #   usable           denials beside the reply (the tools and paths), a warning rate-limit status and
5115: #                    other models become Warnings
5116: function Get-ClaudeTurnOutcome {
5117:     param($Events, [int]$ExitCode, [string]$StderrText = '', [string]$Pre = '', [string]$ExpectThread = '', [string]$ExpectModel = '', $Turn = $null)
5118:     $o = [pscustomobject]@{ Ok = $false; Outcome = ''; Class = ''; Texts = [string[]]@(); Thread = ''; ThreadCandidate = ''; Reply = ''; Structured = $false; DeniedEmpty = $false; DenialLine = ''; Permission = ''; NotFound = ''; Warnings = [string[]]@(); ModelResolved = ''; OtherModels = [string[]]@() }
5119:     $lines = @(([string]$StderrText) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
5120:     $stderrTail = $(if ($lines.Count -gt 0) { [string]$lines[-1] } else { '' })
5121:     $mode = [string](Get-PropertyValue $Turn 'Mode' '')
5122:     $turnThread = [string](Get-PropertyValue $Turn 'Thread' '')
5123:     $newThread = [string](Get-PropertyValue $Turn 'NewThread' '')
5124:     $auth = [string](Get-PropertyValue $Turn 'Auth' '')
5125:     if ($script:ClaudeAuthModes -notcontains $auth) { $auth = 'subscription' }
5126:     # (wave 29b, E2) an endpoint route's model is proven by equality (no alias family)
5127:     $exact = ($auth -eq 'endpoint')
5128:     $pinned = $(if ($ExpectModel) { $ExpectModel } else { [string](Get-PropertyValue $Turn 'Model' '') })
5129:     $forkOf = $(if ($mode -eq 'fork' -and $turnThread) { $turnThread } else { '' })
5130:     $expect = $ExpectThread
5131:     if (-not $expect -and $turnThread -and -not $forkOf) { $expect = $turnThread }
5132:     if (-not $expect -and -not $turnThread -and $newThread) { $expect = $newThread }
5133:     $resId = [string]$Events.Thread
5134:     $initId = [string]$Events.InitThread
5135:     $okId = { param([string]$Id) [bool]($Id -match $script:UuidRe -and (-not $expect -or $Id -eq $expect) -and (-not $forkOf -or $Id -ne $forkOf)) }
5136:     $candidateOf = { param([string]$Id) if ($Id -match $script:UuidRe -and (-not $forkOf -or $Id -ne $forkOf)) { $Id } else { '' } }
5137:     $o.Structured = [bool]$Events.HasStructured
